/* ===== Кабинет · Бумага — тема для Кабинета ===== */
:root {
  --k-paper: #F6F1E7; --k-panel: #FAF6EE; --k-card: #FFFDF8; --k-user: #F3ECDD; --k-field: #FFFDF8;
  --k-ink: #3A352C; --k-muted: #8B8272; --k-em: #6F7F5C; --k-quote: #A0652A; --k-rose: #9A4E5C;
  --k-accent: #6E8566; --k-accent-soft: rgba(110, 133, 102, 0.14); --k-line: rgba(98, 84, 60, 0.16); --k-line-strong: rgba(98, 84, 60, 0.32);
  --k-shadow: rgba(80, 64, 40, 0.07); --k-icon: #5E5648;
  --k-font-body: 'Lora', Georgia, serif;
  --k-font-name: 'Cormorant Garamond', Georgia, serif;
  --k-font-ui: 'Nunito', -apple-system, system-ui, sans-serif;
  --mainFontFamily: var(--k-font-ui);
  --SmartThemeCheckboxTickColor: #FFFDF8;
}
body { font-family: var(--k-font-ui); background-color: var(--k-paper) !important; }

/* --- верхняя панель: плоская, без теней --- */
#top-bar, #top-settings-holder { background: var(--k-panel) !important; box-shadow: none !important; }
#top-bar { border-bottom: 1px solid var(--k-line) !important; }
#top-settings-holder .drawer-icon { color: var(--k-icon) !important; text-shadow: none !important; opacity: .8; font-size: 22px; }
#top-settings-holder .drawer-icon.openIcon { color: var(--k-accent) !important; opacity: 1; }

