/* --- чат и сообщения --- */
#chat { background-color: var(--k-paper) !important; }
#chat .mes {
  background-color: var(--k-card) !important;
  border: 1px solid var(--k-line) !important;
  border-radius: 16px !important;
  margin: 8px 6px !important;
  box-shadow: 0 1px 2px var(--k-shadow) !important;
}
#chat .mes[is_user="true"] { background-color: var(--k-user) !important; }
#chat .mes .name_text {
  font-family: var(--k-font-name); font-style: italic; font-weight: 700;
  font-size: 1.3em; letter-spacing: .01em; color: var(--k-accent) !important;
}
#chat .mes[is_user="true"] .name_text { color: var(--k-rose) !important; }
/* без !important: инлайн-цвета плашек из пресета (шапка, дневник, артефакты) должны оставаться своими */
#chat .mes_text { font-family: var(--k-font-body); line-height: 1.7; color: var(--k-ink); }
#chat .mes_text q, #chat .mes_text q * { color: var(--k-quote); }
#chat .mes_text em, #chat .mes_text i { color: var(--k-em); }
#chat .mes_text strong, #chat .mes_text b { color: var(--k-rose); font-weight: 600; }
#chat .mes_text u { text-decoration-color: var(--k-accent); }
#chat .mes_text hr { border: none !important; height: 1px; margin: 18px 0; background: linear-gradient(90deg, transparent, var(--k-line-strong), transparent); }
#chat .mes_text blockquote { border-left: 3px solid var(--k-accent); background: var(--k-accent-soft); border-radius: 0 10px 10px 0; padding: 4px 12px; }
#chat .mes_text code, #chat .mes_text pre { background: var(--k-field) !important; color: var(--k-ink) !important; border: 1px solid var(--k-line) !important; border-radius: 8px; }
.mes .avatar img { border-radius: 12px !important; border: 1px solid var(--k-line) !important; }
.mes_button, .extraMesButtonsHint, .swipe_left, .swipe_right, .swipes-counter, .mes_edit_buttons .menu_button {
  color: var(--k-muted) !important; text-shadow: none !important; box-shadow: none !important;
}
.timestamp, .mesIDDisplay, .tokenCounterDisplay, .mes_timer { color: var(--k-muted) !important; text-shadow: none !important; }
.mes_reasoning_header { background: var(--k-field) !important; border: 1px solid var(--k-line) !important; border-radius: 10px !important; color: var(--k-muted) !important; }
.mes_reasoning { color: var(--k-muted) !important; font-style: italic; }

/* --- поле ввода --- */
#send_form {
  background: var(--k-panel) !important; border: 1px solid var(--k-line) !important;
  border-radius: 18px 18px 0 0 !important; box-shadow: none !important;
}
#send_textarea { font-family: var(--k-font-body); color: var(--k-ink) !important; background: transparent !important; border: none !important; caret-color: var(--k-accent); }
#send_textarea::placeholder { color: var(--k-muted) !important; font-style: italic; }

/* --- панели, ящики, попапы: без серых градиентов --- */
.drawer-content, #left-nav-panel, #right-nav-panel, .popup, dialog.popup, #extensionsMenu, .options-content, .list-group {
  background-color: var(--k-panel) !important; color: var(--k-ink) !important;
  border: 1px solid var(--k-line) !important; box-shadow: 0 8px 24px var(--k-shadow) !important;
}
.drawer-content, .popup, dialog.popup { border-radius: 16px !important; }
.inline-drawer-header, .inline-drawer-toggle.inline-drawer-header, .standoutHeader, #user-settings-block h4,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
  background-image: none !important; background-color: var(--k-card) !important;
  border: 1px solid var(--k-line) !important; border-radius: 12px !important; color: var(--k-ink) !important; box-shadow: none !important;
}
.inline-drawer-header b, .drawer-content h3, .drawer-content h4 { color: var(--k-ink) !important; }
.inline-drawer-icon { background: transparent !important; color: var(--k-accent) !important; opacity: .55; box-shadow: none !important; text-shadow: none !important; }
.list-group-item:hover, #extensionsMenu .list-group-item:hover { background-color: var(--k-accent-soft) !important; }

/* --- кнопки и поля --- */
.menu_button, .menu_button_icon, .right_menu_button {
  background-color: var(--k-card) !important; color: var(--k-ink) !important;
  border: 1px solid var(--k-line) !important; border-radius: 10px !important; box-shadow: none !important; text-shadow: none !important;
}
.menu_button:hover, .right_menu_button:hover { background-color: var(--k-accent-soft) !important; border-color: var(--k-line-strong) !important; }
.text_pole, textarea:not(#send_textarea), select, input[type="text"], input[type="search"], input[type="number"], input[type="password"],
.select2-container .select2-selection, .select2-dropdown {
  background-color: var(--k-field) !important; color: var(--k-ink) !important;
  border: 1px solid var(--k-line-strong) !important; border-radius: 10px !important; box-shadow: none !important;
}
input[type="checkbox"] {
  background-color: var(--k-field) !important; border: 1.5px solid var(--k-line-strong) !important;
  outline: none !important; box-shadow: none !important; filter: none !important; border-radius: 5px !important;
}
input[type="checkbox"]:checked { background-color: var(--k-accent) !important; border-color: var(--k-accent) !important; }
input[type="range"] { accent-color: var(--k-accent); }

/* --- промпт-менеджер --- */
#completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background: var(--k-card) !important; border: 1px solid var(--k-line) !important; border-radius: 10px !important; color: var(--k-ink) !important;
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled { opacity: .55; }
.prompt-manager-toggle-action.fa-toggle-on { color: var(--k-accent) !important; }

/* --- мелочи --- */
.toast, #toast-container > div.toast { background-color: var(--k-card) !important; background-image: none !important; color: var(--k-ink) !important; border-left: 4px solid var(--k-accent) !important; box-shadow: 0 4px 14px var(--k-shadow) !important; opacity: 1 !important; }
::selection { background: var(--k-accent-soft); }
* { scrollbar-width: thin; scrollbar-color: var(--k-line-strong) transparent; }
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-thumb { background: var(--k-line-strong); border-radius: 6px; }
